    case #selector(zoomIn(_:)):
        return canvasZoomIndex < Self.canvasZoomScales.count - 1
    case #selector(zoomOut(_:)):
        return canvasZoomIndex > 0
    case #selector(zoomToFit(_:)):
        return canvasZoomIndex != 0
